                    request_id?: string;
                    details?: components["schemas"]["DeviceImpactPreview"] & {
                        /** @constant */
                        action?: "revoke";
                        /** @constant */
                        verdict?: "blocked";
                        /** @constant */
                        blockCode?: "unresolved_cash_session";
                    };
